//
//  AutoTraceCarouselData.swift
//  Joodle
//
//  Strokes for the Pro carousel's auto-trace demo: the bundled `AutoTraceSample`
//  photo traced once at Balanced detail via the Auto-Trace Lab, then baked so the
//  paywall replays a fixed result instead of running Vision every time it opens.
//  Points are in `CANVAS_SIZE` (342) space — the same shape `DayEntry.drawingData`
//  stores — so they line up with the square photo shown scaled-to-fit.
//

import Foundation

/// The traced strokes, decoded once. Falls back to empty (the demo then shows the
/// photo alone) if decoding ever fails.
let AUTO_TRACE_DEMO_STROKES: [PathData] = {
  guard let data = Data(base64Encoded: AUTO_TRACE_DEMO_DATA_B64, options: .ignoreUnknownCharacters),
        let decoded = try? JSONDecoder().decode([PathData].self, from: data)
  else { return [] }
  return decoded
}()

/// Total point count across all strokes, so the reveal can march a single
/// wavefront through them in draw order.
let AUTO_TRACE_DEMO_TOTAL_POINTS: Int = AUTO_TRACE_DEMO_STROKES.reduce(0) { $0 + $1.points.count }

private let AUTO_TRACE_DEMO_DATA_B64 = ""
